/**
 * Vertice - Herramienta: Construccion geometrica
 * ------------------------------------------------------------------
 * Detecta las rectas y circunferencias del logo seleccionado, prolonga
 * las rectas hasta los bordes de la mesa de trabajo y acota los angulos
 * de inclinacion.
 *
 * El panel HTML invoca:   CG.construccion('{"rectas":true, ...}')
 * y recibe de vuelta una cadena JSON con el resultado.
 */

if (typeof CG === "undefined") { var CG = {}; }

(function (CG) {

    var NOMBRE_CAPA = "CONSTRUCCION";
    var GRADO = String.fromCharCode(176);       // ° sin depender del encoding

    CG.construccion = function (opcionesJSON) {
        try {
            // El payload lo genera nuestro propio panel, no una fuente externa.
            var opt = eval("(" + opcionesJSON + ")");

            var ctx = CG.contexto();
            if (ctx.error) return '{"ok":false,"error":"' + CG.escapaJSON(ctx.error) + '"}';

            var doc = ctx.doc;
            var diagonal = ctx.diagonal;
            var bounds = ctx.bounds;
            var mesa = ctx.mesa;

            // --- Recoleccion ---
            var paths = [], temporales = [], avisos = [];
            CG.recolectaPaths(ctx.seleccion, paths, temporales, avisos);

            if (paths.length === 0) {
                for (var t0 = 0; t0 < temporales.length; t0++) {
                    try { temporales[t0].remove(); } catch (e) {}
                }
                return '{"ok":false,"error":"No se encontro geometria vectorial en la seleccion.",' +
                       '"avisos":' + listaJSON(avisos) + '}';
            }

            var segmentos = [];
            for (var p = 0; p < paths.length; p++) {
                var ss = CG.segmentosDe(paths[p]);
                for (var q = 0; q < ss.length; q++) segmentos.push(ss[q]);
            }

            // --- Umbrales derivados del tamano real del logo ---
            var cfg = {
                longitudMinima:     diagonal * opt.pctLongMin / 100,
                longitudMinimaOrto: diagonal * opt.pctLongMinOrto / 100,
                tolRecta:           diagonal * opt.pctTolRecta / 100,
                tolCircular:        opt.pctTolCirc / 100,
                radioMinimo:        diagonal * opt.pctRadMin / 100,
                radioMaximo:        diagonal * opt.pctRadMax / 100,
                tolAngulo:          1.0,                  // grados, agrupa colineales
                tolColineal:        diagonal * 0.004,
                tolFusion:          diagonal * 0.015,
                cuerdaMinima:       0.15,
                ajustarOrtogonales: opt.ajustarOrtogonales,
                tolOrtogonal:       opt.tolOrtogonal
            };

            var rectas = (opt.rectas || opt.cotas) ? CG.extraeRectas(segmentos, cfg) : [];
            var circulos = opt.circulos ? CG.extraeCirculos(segmentos, cfg) : [];

            for (var t1 = 0; t1 < temporales.length; t1++) {
                try { temporales[t1].remove(); } catch (e) {}
            }

            // --- Destino ---
            var dest = CG.grupoDestino(doc, NOMBRE_CAPA, ctx.centroX, ctx.centroY, opt.limpiarTodo);
            var capa = dest.capa, raiz = dest.raiz;

            var rgb = CG.hexARgb(opt.color) || [89, 89, 89];
            var rgbCota = CG.hexARgb(opt.colorCota) || [20, 115, 230];

            // Los grosores se derivan del tamano del logo: la construccion se
            // lee igual sea cual sea la escala del documento.
            var est = {
                color: CG.creaColor(doc, rgb[0], rgb[1], rgb[2]),
                grosor: diagonal * opt.pctGrosor / 100,
                punteado: opt.punteado,
                opacidad: opt.opacidad
            };
            var estCota = {
                color: CG.creaColor(doc, rgbCota[0], rgbCota[1], rgbCota[2]),
                grosor: diagonal * opt.pctGrosorCota / 100,
                punteado: opt.punteadoCota,
                opacidad: opt.opacidad
            };

            var nRectas = 0, nCirculos = 0, nCotas = 0;

            // --- Rectas prolongadas ---
            if (opt.rectas && rectas.length) {
                var gR = raiz.groupItems.add();
                gR.name = "Rectas";
                for (var i1 = 0; i1 < rectas.length; i1++) {
                    var rc = rectas[i1];
                    var ar = CG.radianes(rc.ang);
                    var seg = CG.recortaRecta(rc.x0, rc.y0, Math.cos(ar), Math.sin(ar), mesa);
                    if (!seg) continue;
                    CG.dibujaLinea(gR, seg[0], seg[1], est);
                    nRectas++;
                }
                if (gR.pageItems.length === 0) gR.remove();
            }

            // --- Circunferencias ---
            if (opt.circulos && circulos.length) {
                var gC = raiz.groupItems.add();
                gC.name = "Circunferencias";
                var marca = diagonal * 0.012;
                for (var i2 = 0; i2 < circulos.length; i2++) {
                    var ci = circulos[i2];
                    CG.dibujaCirculo(gC, ci.cx, ci.cy, ci.r, est);
                    if (opt.centros) CG.dibujaCruz(gC, ci.cx, ci.cy, marca, est);
                    nCirculos++;
                }
                if (gC.pageItems.length === 0) gC.remove();
            }

            // --- Caja, ejes y diagonales ---
            if (opt.caja) {
                var gB = raiz.groupItems.add();
                gB.name = "Caja y ejes";
                var L = bounds[0], T = bounds[1], R = bounds[2], B = bounds[3];

                CG.dibujaLinea(gB, [L, T], [R, T], est);
                CG.dibujaLinea(gB, [R, T], [R, B], est);
                CG.dibujaLinea(gB, [R, B], [L, B], est);
                CG.dibujaLinea(gB, [L, B], [L, T], est);

                var ejeH = CG.recortaRecta(ctx.centroX, ctx.centroY, 1, 0, mesa);
                var ejeV = CG.recortaRecta(ctx.centroX, ctx.centroY, 0, 1, mesa);
                if (ejeH) CG.dibujaLinea(gB, ejeH[0], ejeH[1], est);
                if (ejeV) CG.dibujaLinea(gB, ejeV[0], ejeV[1], est);

                if (opt.diagonales) {
                    CG.dibujaLinea(gB, [L, B], [R, T], est);
                    CG.dibujaLinea(gB, [L, T], [R, B], est);
                }
            }

            // --- Cotas de angulo ---
            var angulos = [];
            if (opt.cotas && rectas.length) {
                // Una sola cota por familia de paralelas.
                var familias = [];
                for (var i3 = 0; i3 < rectas.length; i3++) {
                    var rr = rectas[i3], fam = null;
                    for (var f = 0; f < familias.length; f++) {
                        if (CG.deltaAnguloRecta(familias[f].ang, rr.ang) <= cfg.tolAngulo) {
                            fam = familias[f]; break;
                        }
                    }
                    if (fam) {
                        if (rr.largoTotal > fam.largoTotal) {
                            fam.ang = rr.ang; fam.largoTotal = rr.largoTotal;
                            fam.x0 = rr.x0; fam.y0 = rr.y0; fam.x1 = rr.x1; fam.y1 = rr.y1;
                        }
                    } else {
                        familias.push({
                            ang: rr.ang, largoTotal: rr.largoTotal,
                            x0: rr.x0, y0: rr.y0, x1: rr.x1, y1: rr.y1
                        });
                    }
                }

                var gA = raiz.groupItems.add();
                gA.name = "Cotas de angulo";

                var radioCota = diagonal * opt.pctRadioCota / 100;
                var tamTexto = Math.max(4, diagonal * opt.pctTextoCota / 100);

                for (var i4 = 0; i4 < familias.length; i4++) {
                    var fa = familias[i4];

                    var esOrto = CG.deltaAnguloRecta(fa.ang, 0) < 0.5 ||
                                 CG.deltaAnguloRecta(fa.ang, 90) < 0.5;
                    if (esOrto && !opt.cotasOrtogonales) continue;

                    // Vertice = extremo inferior; el arco abre entre la horizontal
                    // hacia la derecha y la propia recta.
                    var vx, vy, ox, oy;
                    if (fa.y0 <= fa.y1) { vx = fa.x0; vy = fa.y0; ox = fa.x1; oy = fa.y1; }
                    else                { vx = fa.x1; vy = fa.y1; ox = fa.x0; oy = fa.y0; }

                    var angDir = CG.grados(Math.atan2(oy - vy, ox - vx));
                    if (angDir < 0) angDir += 360;
                    if (angDir > 180) angDir -= 180;

                    // Una horizontal con decimas de deriva se leeria como 179.9.
                    if (opt.ajustarOrtogonales) {
                        if (angDir <= opt.tolOrtogonal || angDir >= 180 - opt.tolOrtogonal) angDir = 0;
                        else if (Math.abs(angDir - 90) <= opt.tolOrtogonal) angDir = 90;
                    }

                    // La cota se desplaza por su propia recta hasta salir de la
                    // caja del logo. 1.7 radios es la holgura minima para que ni
                    // el arco ni la etiqueta (que sube 1.42 radios) la toquen.
                    if (opt.cotasFuera && angDir > 0.5 && angDir < 179.5) {
                        var arD = CG.radianes(angDir);
                        var sn = Math.sin(arD);
                        if (Math.abs(sn) > CG.EPS) {
                            var tt = (vy - (bounds[3] - radioCota * 1.7)) / sn;
                            if (tt > 0) {
                                var nvx = vx - tt * Math.cos(arD);
                                var nvy = vy - tt * sn;
                                var h = radioCota * 1.6;
                                if (nvx - h > mesa[0] && nvx + h < mesa[2] &&
                                    nvy - h > mesa[3] && nvy + h < mesa[1]) {
                                    vx = nvx; vy = nvy;
                                }
                            }
                        }
                    }

                    var arDir = CG.radianes(angDir);
                    CG.dibujaLinea(gA, [vx, vy], [vx + radioCota * 1.35, vy], estCota);
                    CG.dibujaLinea(gA, [vx, vy],
                        [vx + radioCota * 1.35 * Math.cos(arDir),
                         vy + radioCota * 1.35 * Math.sin(arDir)], estCota);

                    CG.dibujaArco(gA, vx, vy, radioCota, 0, angDir, estCota);

                    var aMed = CG.radianes(angDir / 2);
                    CG.dibujaTexto(gA, angDir.toFixed(1) + GRADO,
                        vx + radioCota * 1.42 * Math.cos(aMed),
                        vy + radioCota * 1.42 * Math.sin(aMed),
                        tamTexto, estCota.color);

                    angulos.push(angDir.toFixed(1));
                    nCotas++;
                }

                if (gA.pageItems.length === 0) gA.remove();
            }

            // --- Cierre ---
            if (raiz.pageItems.length === 0) {
                raiz.remove();
                if (capa.pageItems.length === 0) capa.remove();
                return '{"ok":false,"error":"No se detecto ningun elemento con estos ajustes. ' +
                       'Baja la longitud minima de recta o sube la tolerancia de circularidad.",' +
                       '"avisos":' + listaJSON(avisos) + '}';
            }

            if (opt.bloquear) capa.locked = true;
            doc.selection = null;
            app.redraw();

            return '{"ok":true,' +
                   '"grupo":"' + CG.escapaJSON(dest.nombre) + '",' +
                   '"rectas":' + nRectas + ',' +
                   '"circulos":' + nCirculos + ',' +
                   '"cotas":' + nCotas + ',' +
                   '"angulos":' + listaJSON(angulos) + ',' +
                   '"grosor":' + est.grosor.toFixed(2) + ',' +
                   '"grosorCota":' + estCota.grosor.toFixed(2) + ',' +
                   '"avisos":' + listaJSON(avisos) + '}';

        } catch (e) {
            return '{"ok":false,"error":"' + CG.escapaJSON("Error interno: " + e + " (linea " + e.line + ")") + '"}';
        }
    };

    /** Serializa un array de cadenas a JSON sin depender de un parser. */
    function listaJSON(arr) {
        var out = [];
        for (var i = 0; i < arr.length; i++) out.push('"' + CG.escapaJSON(arr[i]) + '"');
        return "[" + out.join(",") + "]";
    }

})(CG);
